import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.*;

public class DownloadServlet extends HttpServlet {
    private static final Path BASE_DIR = Paths.get("/var/www/files").toRealPath();

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws IOException {

        String fileName = request.getParameter("fileName");

        if (fileName == null || fileName.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing file name");
            return;
        }

        // Resolve the requested path, normalize it, and ensure it stays inside the base directory.
        Path requestedPath = BASE_DIR.resolve(fileName).normalize().toRealPath();

        if (!requestedPath.startsWith(BASE_DIR)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Invalid file path");
            return;
        }

        try (InputStream inputStream = Files.newInputStream(requestedPath)) {
            response.setContentType("application/octet-stream");

            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                response.getOutputStream().write(buffer, 0, bytesRead);
            }
        }
    }
}

